    "content": "11月20日是世界儿童日。今年恰逢联合国儿童基金会成立80周年，世界儿童日全球主题为“Choose a Future for Children”，中文主题词为“携手向光前行，点亮儿童未来”。从城市到乡村，这束光照亮了孩子们。 在中国儿童中心的活动现场，参加世界儿童日征文和绘画活动的儿童代表分享了他们对未来的期待。一张张画作、一篇篇征文，是孩子们对世界最纯粹的憧憬。 “我们必须选择倾听儿童的心声，选择投资于儿童，选择维护儿童权利，守护儿童的福祉。因为选择儿童，就是选择全人类更美好的明天。”联合国助理秘书长、联合国儿童…"
