    "description": "新华社开普敦11月20日电（记者王晓梅 王雷）受水库蓄水量下降和用水需求增长等影响，南非多地政府近日发布公告，宣布实施限水措施，以缓解供水压力。 南非第一大城市约翰内斯堡市政府18日发布公告，宣布于本月21日起实施2级限水措施。据当地水务部门估计，该市每日需减少2亿升用水，才能有效缓解供水压力。立法首都开普敦市政府16日发布公告，宣布自12月1日起实施1级限水措施，要求居民、游客和企业将用水量降低至少10%。此外，行政首都比勒陀利亚所在…",
    "content": "新华社开普敦11月20日电（记者王晓梅 王雷）受水库蓄水量下降和用水需求增长等影响，南非多地政府近日发布公告，宣布实施限水措施，以缓解供水压力。 南非第一大城市约翰内斯堡市政府18日发布公告，宣布于本月21日起实施2级限水措施。据当地水务部门估计，该市每日需减少2亿升用水，才能有效缓解供水压力。立法首都开普敦市政府16日发布公告，宣布自12月1日起实施1级限水措施，要求居民、游客和企业将用水量降低至少10%。此外，行政首都比勒陀利亚所在的茨瓦内市已于16日起实施2级限水措施。 南非各地分级限水措施的具体规定有所不同…"
