    "content": "11月20日，嘉宾出席世界记忆与世界遗产及非物质文化遗产的协同发展国际研讨会揭幕仪式。新华社发（张金加摄） 新华社澳门11月20日电（记者齐菲、宋晨）世界记忆与世界遗产及非物质文化遗产的协同发展国际研讨会20日在澳门举行，以“三遗协同”为核心议题，凸显三项遗产的内在联系与各自功能，并通过对话促进相互合作。 澳门特区政府社会文化司司长代表、文化体育局局长梁惠敏致辞表示，澳门拥有世界遗产、丰富的非物质文化遗产，在文献遗产领域也硕果累累。未来，澳门将持续开展本地文献档案的挖掘与梳理；借助数字科技等手段推动文献创造性转化；…"
