    "description": "新华社郑州11月20日电（记者袁月明）11月20日，由中央精神文明建设办公室、中央网信办、教育部等部门组织发起的“网络文明大讲堂·数字里的文化遗产”专场活动在河南郑州举办。 本次活动汇聚文化遗产领域多名专家学者、网络创作者等，旨在运用“网络文明大讲堂”这一平台，深入探讨文化遗产保护传承如何与网络文明建设双向奔赴，以优秀传统文化推动互联网向上向善，更好地造福人民。 与会嘉宾表示，文物和文化遗产承载着中华民族的基因和血脉，是不可再生、不可替…",
    "content": "新华社郑州11月20日电（记者袁月明）11月20日，由中央精神文明建设办公室、中央网信办、教育部等部门组织发起的“网络文明大讲堂·数字里的文化遗产”专场活动在河南郑州举办。 本次活动汇聚文化遗产领域多名专家学者、网络创作者等，旨在运用“网络文明大讲堂”这一平台，深入探讨文化遗产保护传承如何与网络文明建设双向奔赴，以优秀传统文化推动互联网向上向善，更好地造福人民。 与会嘉宾表示，文物和文化遗产承载着中华民族的基因和血脉，是不可再生、不可替代的中华优秀文明资源。要以数智技术赋能文化遗产保护，以丰厚文化遗产滋养网络文明，…"
