    "content": "新华社南宁11月20日电（记者陈露缘）记者20日从广西壮族自治区政府新闻办公室举行的新闻发布会获悉，目前广西在册东盟留学生超8300人，约占来桂留学生总数的66%，广西对东盟学子的吸引力持续提升。 近年来，广西发挥面向东盟的区位优势，持续完善面向东盟的人才培育体系，推进中国—东盟经济学院、法学院、统计学院、航天工程师学院以及10个技术创新学院建设；积极推动职业教育发展，截至目前，19所中国—东盟现代工匠学院实现东盟11国全覆盖，累计培养学历教育学生1500余人，开展非学历培训6万余人次。 自治区教育厅副厅长傅源方介…"
