    "description": "新华社香港11月20日电（谢妞）由亚太青年企业家联盟主办、香港菁英会合办的亚太经合组织（APEC）新世代青年企业家峰会20日在港举行。 本次峰会以“从构思到影响：青年企业家驱动亚太增长”为主题，汇聚逾400位亚太区青年企业家与商界领袖等，共同探讨如何将创新构思转化为实质影响力，携手推动亚太区域的经济增长。 开幕仪式上，香港特区行政长官李家超视频致辞表示，本次峰会的与会者来自不同领域，旨在建立跨经济体联系，为APEC政策考量提供参考。香港…",
    "content": "新华社香港11月20日电（谢妞）由亚太青年企业家联盟主办、香港菁英会合办的亚太经合组织（APEC）新世代青年企业家峰会20日在港举行。 本次峰会以“从构思到影响：青年企业家驱动亚太增长”为主题，汇聚逾400位亚太区青年企业家与商界领袖等，共同探讨如何将创新构思转化为实质影响力，携手推动亚太区域的经济增长。 开幕仪式上，香港特区行政长官李家超视频致辞表示，本次峰会的与会者来自不同领域，旨在建立跨经济体联系，为APEC政策考量提供参考。香港作为粤港澳大湾区核心的国际枢纽，是青年企业家拓展事业的理想平台。香港连接内地与世…"
