    "description": "新华社北京11月20日电 国家互联网信息办公室20日就《实施网络安全标识的产品目录（第二批）》公开征求意见，意见反馈截止时间为2026年12月20日。据悉，实施网络安全标识的产品目录（第二批）包括消费类智能门锁、智能音箱、儿童智能手表。 国家网信办还对消费类智能门锁网络安全标识实施规则（征求意见稿）、智能音箱网络安全标识实施规则（征求意见稿）、儿童智能手表网络安全标识实施规则（征求意见稿）公开征求意见。 根据征求意见稿，消费类智能门锁、…",
    "content": "新华社北京11月20日电 国家互联网信息办公室20日就《实施网络安全标识的产品目录（第二批）》公开征求意见，意见反馈截止时间为2026年12月20日。据悉，实施网络安全标识的产品目录（第二批）包括消费类智能门锁、智能音箱、儿童智能手表。 国家网信办还对消费类智能门锁网络安全标识实施规则（征求意见稿）、智能音箱网络安全标识实施规则（征求意见稿）、儿童智能手表网络安全标识实施规则（征求意见稿）公开征求意见。 根据征求意见稿，消费类智能门锁、智能音箱、儿童智能手表的网络安全标识对应的网络安全能力由低到高依次为基础级、增强…"
