    "description": "36氪获悉，易天股份公告，公司拟以现金收购深圳市艾晨数字能源有限公司37%股权，并与标的公司部分股东签署《一致行动协议》，预计交易完成后公司及一致行动主体合计持有标的公司股份比例约51.8490%。标的公司主营数据中心关键基础设施与智慧储能系统的研发、生产和销售，有助于促进公司储备一体化业务发展。",
