    "content": "（深圳综合讯）美国总统特朗普访问中国深圳期间，中国官方在宴会上安排有“特朗普竞选神曲”之称的《YMCA》歌舞表演，特朗普和中国国家主席习近平坐在台下共同观赏。 亚太经合组织（APEC）会议星期四（11月19日）落幕后，白宫特别助理兼通讯顾问马丁（Margo Martin）在社媒X发布一段18秒短视频，显示特朗普和习近平并排坐在主桌，一同观看《YMCA》歌舞表演。根据美方此前公布的行程信息，这场表演相信是在星期四下午的中美元首午宴上进行的。 视频画面显示，20多名身着五颜六色服饰的中国表演者在台上载歌载舞，后方大屏幕…"
