    "content": "新华社北京11月20日电（记者张千千）国家金融监督管理总局11月20日发布的数据显示，三季度末，银行业金融机构普惠型小微企业贷款余额38.8万亿元，同比增长6.4%；普惠型涉农贷款余额15万亿元，同比增长6.2%。 今年前三季度，保险公司原保险保费收入5.3万亿元，同比增长0.9%；赔款与给付支出1.9万亿元，同比增长3.9%；新增保单件数1010亿件，同比增长19.3%。 银行业和保险业总资产保持增长。三季度末，我国银行业金融机构本外币资产总额503.1万亿元，同比增长6.1%；保险公司和保险资产管理公司总资产4…"
