    "content": "新华社北京11月20日电 今年以来，证券监管部门联合公安机关查办多个编造传播资本市场虚假信息的违法违规行为。11月20日，中国证监会和公安部联合公布4起编造传播资本市场虚假信息典型案例。 案例一：宗某、卢某等编造传播行业税收政策谣言，扰乱市场预期。 2026年2月，宗某捏造“互联网要按25%交税”消息发布至互联网。该谣言传播扩散后，对市场秩序造成干扰。公安机关已依法对宗某作出行政处罚。卢某对某App人工智能生成的“游戏等互联网增值服务增值税税率将从6%调高至32%”相关信息未加甄别上传网络，陈某看到后转发至本人自媒…"
