    "description": "新华社东京11月20日电（记者李子越 杨智翔）日本多个民间团体20日向防卫省递交由4.7万名日本民众联合签名的材料，反对日本拥有核动力潜艇，要求政府撤回相关计划。 记者从民间团体方面获悉，此次联合签名活动由“日本原子力资料情报室”等民间机构和组织共同发起，在约一个月时间内就征集到4.7万人签名。 此次联合签名活动的声明指出，日本作为唯一遭受过原子弹轰炸的国家，一直宣称有责任推动废除核武器，而拥有核动力潜艇无异于主动背弃这一承诺。 在递交…",
    "content": "新华社东京11月20日电（记者李子越 杨智翔）日本多个民间团体20日向防卫省递交由4.7万名日本民众联合签名的材料，反对日本拥有核动力潜艇，要求政府撤回相关计划。 记者从民间团体方面获悉，此次联合签名活动由“日本原子力资料情报室”等民间机构和组织共同发起，在约一个月时间内就征集到4.7万人签名。 此次联合签名活动的声明指出，日本作为唯一遭受过原子弹轰炸的国家，一直宣称有责任推动废除核武器，而拥有核动力潜艇无异于主动背弃这一承诺。 在递交联署材料后的记者会上，民间团体代表表示，日本政府一方面探讨引进核动力潜艇，另一方…"
