    "content": "新华社北京11月20日电（记者伍岳）11月20日下午，国务院总理李强在北京钓鱼台国宾馆同澳大利亚总理阿尔巴尼斯举行第十一轮中澳总理年度会晤。 李强表示，当前，中澳关系保持积极发展势头，各层级交往日益密切，各领域合作走深走实，给两国人民带来实实在在的利益。今天上午，习近平主席在深圳同总理先生举行会晤，就进一步深化中澳关系作出战略指引。明年是中澳建交55周年，中方愿同澳方一道以此为契机，秉持平等互利、开放务实态度，聚焦共同利益，妥善管控分歧，推动中澳全面战略伙伴关系取得更多积极成效，共促两国发展繁荣。 李强指出，中澳在…"
