    "link": "https://www.infzm.com/contents/345294",
    "pub_date": "2026-11-20 19:17:40",
    "author": "",
    "description": "条文亟须在草案基础上继续优化取保候审、拘留、逮捕的适用，实现强制措施的梯度化、精准化适用，减少不必要的羁押，扩大非羁押适用。 李奋飞｜中国人民大学法学院、纪检监察学院双聘教授 责任编辑：杜茂林 2026年11月，刑事诉讼法修正草案提请十四届全国人大常委会第二十五次会议初次审议，并在中国人大网公开征求意见。修正草案回应了社会广泛关注的指定居所监视居住、涉案财物处置等问题。尤其值得充分肯定的是，备受质疑的指定居所监视居住虽未被废除，但适用范…",
    "content": "条文亟须在草案基础上继续优化取保候审、拘留、逮捕的适用，实现强制措施的梯度化、精准化适用，减少不必要的羁押，扩大非羁押适用。 草案仍缺少规范查扣行为的刚性规则，查扣全过程依旧存在“暗箱操作”空间，亟须在修正草案基础上，新增两大核心制度：全程同步录音录像制度、律师在场制度。 李奋飞｜中国人民大学法学院、纪检监察学院双聘教授 责任编辑：杜茂林 2026年11月，刑事诉讼法修正草案提请十四届全国人大常委会第二十五次会议初次审议，并在中国人大网公开征求意见。修正草案回应了社会广泛关注的指定居所监视居住、涉案财物处置等问题。…"
