    "description": "新华社天津11月20日电（记者包庆龄）红砖、石阶、圆柱、尖塔、雕花，眼前这座富有浓郁异国风情的建筑便是天津西站老站房。初冬的晴日下，不断有游客从两旁的阶梯拾级而上进入其中。他们将要看到的，是一个熟悉又陌生的老西站。 有着百余年历史的天津西站老站房，以“西站艺术中心”的崭新面貌正式对外开放，沉寂了数年的老站房，重新进入天津人的城市生活中。 11月19日，游客在天津西站老站房外观光拍照。新华社发 西站老站房的历史，要追溯至100多年前。天津…",
    "content": "新华社天津11月20日电（记者包庆龄）红砖、石阶、圆柱、尖塔、雕花，眼前这座富有浓郁异国风情的建筑便是天津西站老站房。初冬的晴日下，不断有游客从两旁的阶梯拾级而上进入其中。他们将要看到的，是一个熟悉又陌生的老西站。 有着百余年历史的天津西站老站房，以“西站艺术中心”的崭新面貌正式对外开放，沉寂了数年的老站房，重新进入天津人的城市生活中。 11月19日，游客在天津西站老站房外观光拍照。新华社发 西站老站房的历史，要追溯至100多年前。天津西站老站房于1910年投入运营，是津浦铁路北端起点，也是国内铁路枢纽中建成较早、…"
