    "content": "新华社郑州11月20日电（记者王烁、吴刚）秋冬交替，气温波动加大，心血管事件进入高发时段。11月20日是“中国心梗救治日”。专家提示，心脏疾病的危险信号容易被忽视，不要让最佳救治期被“忍一忍”耽误。 医生在为病人进行心脏射频消融手术。新华社发 读懂心脏求救信号 专家表示，出现胸痛、胸闷、心慌等不适，切莫大意。“有以下四类情况要立即就医。”阜外华中心血管病医院心律失常一病区主任杨海涛表示，一是胸骨后或心前区压榨样、憋闷样痛感，可放射到左肩、后背、下颌乃至牙齿；二是胸闷胸痛持续超过20分钟，休息后不缓解，并伴有出冷汗、…"
