    "content": "记者11月20日从中国人民银行获悉，中国人民银行定于2026年11月27日发行2027中国丁未（羊）年贵金属纪念币一套。该套贵金属纪念币共11枚，其中金质纪念币6枚，银质纪念币4枚，铂质纪念币1枚，均为中华人民共和国法定货币。 该套贵金属纪念币正面图案均为中华人民共和国国徽，衬以中国传统吉祥纹饰，并刊国名、年号。其中，10公斤圆形金质纪念币背面图案为羊群造型，衬以太阳、山水、草地等组合设计，含纯金10公斤，最大发行量18枚。 1公斤梅花形金质纪念币背面图案为羊造型，衬以草地、山、云组合设计，含纯金1公斤，最大发行量…"
