    "pub_date": "2026-11-20 18:50:57",
    "author": "",
    "description": "新华社上海11月20日电（记者袁全）11月20日是中国心梗救治日。急性心肌梗死具有发病急、致死率高、致残率高、救治时间窗口窄的特点，是临床最为凶险的心血管急症之一。随着冬季气温下降，血管跟着“缩脖子”，急性心肌梗死进入高发季。急诊医生提醒：心梗病情判断不能仅以“疼不疼”为标准，即便疼痛症状缓解，也需警惕症状缓解背后的致命风险。 “临床上不少患者在胸痛自行缓解后便认为无需就医，这是极具危险性的错误判断。”同济大学附属同济医院急诊内科主治医…",
    "content": "新华社上海11月20日电（记者袁全）11月20日是中国心梗救治日。急性心肌梗死具有发病急、致死率高、致残率高、救治时间窗口窄的特点，是临床最为凶险的心血管急症之一。随着冬季气温下降，血管跟着“缩脖子”，急性心肌梗死进入高发季。急诊医生提醒：心梗病情判断不能仅以“疼不疼”为标准，即便疼痛症状缓解，也需警惕症状缓解背后的致命风险。 “临床上不少患者在胸痛自行缓解后便认为无需就医，这是极具危险性的错误判断。”同济大学附属同济医院急诊内科主治医师熊雅南解释，疼痛缓解存在两种并不乐观的病理可能：一是缺血区域的心肌已经坏死，能…"
