    "description": "11月20日，首届历史经典产业博览会在杭州启幕。丝绸、茶叶、瓷器、中药、酿造、工艺美术等行业集中亮相……这些镌刻着中华文明印记的古老手艺，承载着中华民族文化的根脉。当传统技艺遇上现代科技、对接新的消费场景，它们如何焕发新的光彩？让我们跟随新华社记者奔赴产业一线，看看这些历史经典产业的新故事。 ■天津漆艺：失传古技的当代重生 天津郑氏陶胎漆艺依托高校多学科科研力量，攻克陶漆相融核心难题，复原一度失传的陶胎漆器技艺。团队践行“艺工结合”理念…",
    "content": "11月20日，首届历史经典产业博览会在杭州启幕。丝绸、茶叶、瓷器、中药、酿造、工艺美术等行业集中亮相……这些镌刻着中华文明印记的古老手艺，承载着中华民族文化的根脉。当传统技艺遇上现代科技、对接新的消费场景，它们如何焕发新的光彩？让我们跟随新华社记者奔赴产业一线，看看这些历史经典产业的新故事。 ■天津漆艺：失传古技的当代重生 天津郑氏陶胎漆艺依托高校多学科科研力量，攻克陶漆相融核心难题，复原一度失传的陶胎漆器技艺。团队践行“艺工结合”理念，依托本硕博人才培养体系，把手工技艺转化为教学课程，打通实验室到工坊的产业化路径…"
