    "description": "新华社哈尔滨11月20日电 题：黑龙江：“冷资源”释放冰雪经济“热效应” 新华社记者刘赫垚 进入冬季，黑龙江气温走低，但“冰雪热”加速升温。冰雪旅游市场人气渐旺、冰雪装备制造企业马力全开……蓬勃的冰雪经济图景在龙江大地徐徐展开。 19日，伴着纷纷扬扬的雪花，“中国雪乡”景区开园。人声鼎沸的雪韵大街上，锣鼓铿锵，秧歌欢舞，火热的民俗表演热闹上演。“很幸运赶上雪乡开园，从未见过这么美的雪景，氛围也特别好！”广东游客钟女士说。 龙江森工集团大…",
    "content": "新华社哈尔滨11月20日电 题：黑龙江：“冷资源”释放冰雪经济“热效应” 新华社记者刘赫垚 进入冬季，黑龙江气温走低，但“冰雪热”加速升温。冰雪旅游市场人气渐旺、冰雪装备制造企业马力全开……蓬勃的冰雪经济图景在龙江大地徐徐展开。 19日，伴着纷纷扬扬的雪花，“中国雪乡”景区开园。人声鼎沸的雪韵大街上，锣鼓铿锵，秧歌欢舞，火热的民俗表演热闹上演。“很幸运赶上雪乡开园，从未见过这么美的雪景，氛围也特别好！”广东游客钟女士说。 龙江森工集团大海林林业局有限公司森林旅游产业发展部部长冯慧强介绍，景区今冬围绕品质、体验、服务…"
