    "description": "新华社昆明11月20日电（记者熊轩昂、胡超）11月20日，全国政协副主席王勇在云南会见参加“红色研学之旅”的中越青年代表，出席越南－中国西南地区发展战略对接论坛。 会见青年代表时，王勇表示，习近平总书记指出，中越友好的根基在人民、未来在青年。两国青年要赓续“同志加兄弟”传统友谊，走近走亲、融通同心，为中越友好发展注入蓬勃青春活力。 出席论坛时，王勇表示，中方愿同越方加强战略对接，深化务实合作，密切人文交流，共促发展繁荣，携手构建更高水平…",
    "content": "新华社昆明11月20日电（记者熊轩昂、胡超）11月20日，全国政协副主席王勇在云南会见参加“红色研学之旅”的中越青年代表，出席越南－中国西南地区发展战略对接论坛。 会见青年代表时，王勇表示，习近平总书记指出，中越友好的根基在人民、未来在青年。两国青年要赓续“同志加兄弟”传统友谊，走近走亲、融通同心，为中越友好发展注入蓬勃青春活力。 出席论坛时，王勇表示，中方愿同越方加强战略对接，深化务实合作，密切人文交流，共促发展繁荣，携手构建更高水平具有战略意义的中越命运共同体。 越共中央总书记、国家主席苏林出席上述活动，寄语两…"
