    "description": "新华社北京11月20日电（记者陈旭）北京市住房和城乡建设委员会会同北京市市场监督管理局起草的《北京市住房租赁合同（示范文本）（修订征求意见稿）》20日起向社会公开征集意见，征求意见稿细化租赁资金安全保护、房屋安全使用、个人信息保护等内容，拟明确房屋正常损耗，出租人不得以此为由扣减承租人押金。 北京市现行住房租赁合同示范文本自2023年发布以来，在规范住房租赁市场秩序、保护租赁双方合法权益方面发挥了积极作用。近年来，因押金返还、住房维修、…",
    "content": "新华社北京11月20日电（记者陈旭）北京市住房和城乡建设委员会会同北京市市场监督管理局起草的《北京市住房租赁合同（示范文本）（修订征求意见稿）》20日起向社会公开征集意见，征求意见稿细化租赁资金安全保护、房屋安全使用、个人信息保护等内容，拟明确房屋正常损耗，出租人不得以此为由扣减承租人押金。 北京市现行住房租赁合同示范文本自2023年发布以来，在规范住房租赁市场秩序、保护租赁双方合法权益方面发挥了积极作用。近年来，因押金返还、住房维修、住房腾退等产生的纠纷时有发生，社会公众对完善租赁合同条款、强化租赁当事人权益保护…"
