    "content": "中新网广西玉林11月20日电(记者 黄艳梅)2026年广西数字乡村建设工作推进会近日在广西玉林市举行。记者从会上获悉，广西将织密乡村数字底座，提升产业数字化水平，提高乡村治理数字化效能，扎实推进“十五五”数字乡村高质量发展。"
