    "description": "新华社北京11月20日电 记者从中国铁建股份有限公司获悉，20日，由中国铁建大桥局承建的上海G1503公路中心线延伸线项目首片箱梁精准落位，标志着此项目桥梁上部结构施工全面展开。 据中国铁建大桥局此项目负责人介绍，此次吊装的首件箱梁长28.2米、宽4米、重约127.7吨。施工现场紧邻G1503公路，车流密集、作业面受限，箱梁运输与对位精度要求高。项目团队配置专职人员负责信号指挥与安全监护，确保箱梁精准入位。 上海G1503公路中心线延伸…",
    "content": "新华社北京11月20日电 记者从中国铁建股份有限公司获悉，20日，由中国铁建大桥局承建的上海G1503公路中心线延伸线项目首片箱梁精准落位，标志着此项目桥梁上部结构施工全面展开。 据中国铁建大桥局此项目负责人介绍，此次吊装的首件箱梁长28.2米、宽4米、重约127.7吨。施工现场紧邻G1503公路，车流密集、作业面受限，箱梁运输与对位精度要求高。项目团队配置专职人员负责信号指挥与安全监护，确保箱梁精准入位。 上海G1503公路中心线延伸线项目是上海东站与浦东国际机场南片区之间的重要东西向通道，建成后将进一步强化沿线…"
