    "description": "国际法院裁定缅甸对罗兴亚少数族群实施种族灭绝后，中国外交部对越权管辖、扩大解释等问题表示关切，认为有关做法不利于解决争端。 中国外交部发言人郭嘉昆星期五（11月20日）在例行记者会上说，若开邦问题有着非常复杂的历史民族和宗教背景，需要综合施策稳妥解决，国际社会应为此共同努力，避免将这一问题复杂化。 他指出，中国愿继续支持有关各方加强对话协商，为推动解决若开邦避乱民众遣返问题发挥建设性作用。 郭嘉昆还说，国际司法机构是维护国际公平正义的重…",
    "content": "国际法院裁定缅甸对罗兴亚少数族群实施种族灭绝后，中国外交部对越权管辖、扩大解释等问题表示关切，认为有关做法不利于解决争端。 中国外交部发言人郭嘉昆星期五（11月20日）在例行记者会上说，若开邦问题有着非常复杂的历史民族和宗教背景，需要综合施策稳妥解决，国际社会应为此共同努力，避免将这一问题复杂化。 他指出，中国愿继续支持有关各方加强对话协商，为推动解决若开邦避乱民众遣返问题发挥建设性作用。 郭嘉昆还说，国际司法机构是维护国际公平正义的重要工具，更要依法审慎行使职权。中国对越权管辖和扩大解释等问题存在关切，认为有关做…"
