    "content": "新华社莫斯科11月20日电 据俄新社报道，俄罗斯外交部副部长里亚布科夫20日表示，乌克兰加入北约对俄方而言“完全不可接受”，为乌方谋求“准成员国”地位或寻找某种“创造性解决方案”也不会被俄方接受。 里亚布科夫当天在圣彼得堡出席活动时说，鉴于欧盟“日益咄咄逼人”的姿态、鲜明的反俄路线以及持续军事化，俄方认为，欧盟与北约之间“没有多大差别”。 里亚布科夫表示，俄罗斯、美国和乌克兰日前在阿联酋首都阿布扎比举行会谈。就是否按照这一模式举行新一轮会谈，俄方未同有关方面达成共识或约定。此外，俄方已决定邀请欧洲代表访问莫斯科，此…"
