    "description": "新华社北京11月20日电 题：这部剧为何让人追着落泪 新华社记者杨淑君 60集重大革命题材电视剧《伟大的长征》日前收官，“每一集都有泪点”“这盛世如你所愿”“60集看不够”……弹幕一行行刷过，朴素字句里涌动滚烫情感。一段结局早已写定的历史，一部人人熟知来路的剧，何以让这么多人红着眼眶看完？ 以真实致敬历史，让信仰在细节中具象—— 长征故事家喻户晓，越是熟悉，越考验创作诚意。为了全景式展现艰苦卓绝的长征历程，主创团队三次重走长征路，查阅收…",
