    "content": "新华社太原11月20日电（记者王飞航）记者近日从山西省统计局获悉，今年10月山西原煤产量达到8297.1万吨，较9月增加414万吨左右，增幅约5%。 据介绍，今年夏季以来，山西煤炭生产曾经历一段承压期。受全省安全整治影响，一批矿井停产整改，6月至8月山西原煤产量同比降幅均超过30%。进入9月后，山西煤炭生产开始逐步恢复。10月产量进一步回升，显示出停产矿井有序复产、正常生产矿井优化组织、在建矿井加快投产的综合成效。 山西朔州中煤平朔集团东露天矿的装车现场，一辆辆重型卡车排成长队，铲斗起落间，新采出的原煤被源源不断装…"
